def generate_random_kcnf(n, k):
    clauses = []
    for _ in range(k * n):
        clause = set()
        while len(clause) < 2:
            var = random.randint(1, n)
            sign = random.choice([1, -1])
            clause.add((var, sign))
        clauses.append(list(clause))
    return clauses

def gaussian_elimination(matrix):
    rows, cols = len(matrix), len(matrix[0])
    for i in range(rows):
        max_row = i
        for j in range(i + 1, rows):
            if abs(matrix[j][i]) > abs(matrix[max_row][i]):
                max_row = j
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]
        factor = Fraction(matrix[i][i])
        for j in range(cols):
            matrix[i][j] /= factor
        for j in range(rows):
            if i != j:
                factor = Fraction(matrix[j][i])
                for k in range(cols):
                    matrix[j][k] -= factor * matrix[i][k]
    return matrix

def min_noncommutative_rank(clauses):
    n = len(clauses)
    matrix = [[0] * (2 * n) for _ in range(2 * n)]
    for i, clause in enumerate(clauses):
        for var, sign in clause:
            row = 2 * var - 1 if sign == 1 else 2 * var
            col = 2 * var - 2 if sign == 1 else 2 * var - 1
            matrix[row][col] += 1
    rank = 0
    for i in range(2 * n):
        if any(matrix[i][j] != 0 for j in range(rank, 2 * n)):
            rank += 1
    return rank

def resolution_depth(clauses):
    stack = []
    while clauses:
        new_clause = None
        for clause in clauses:
            if len(clause) == 1:
                literal = clause[0]
